    "history": "Dhokra metal figurines are traditional cast-metal objects produced using the lost-wax technique. Artisans shape a model in wax, cover it with clay, and heat the mould to remove the wax. Molten metal is then poured into the cavity, and after cooling, the mould is broken to reveal the figure. In Odisha, Dhokra craftsmanship is associated with artisan communities, including the recognised craft centre of Sadeibarani in Dhenkanal district. Figurines may depict deities, musicians, people, and animals. Their distinctive textures reflect the skill and heritage of traditional metal casting.",
